// Template helper
function makeOpp(params) {
  return {
    site_name: params.name,
    domain: params.domain,
    exact_submission_url: params.url,
    region: params.region,
    country: params.country || (params.region === "INDIA" ? "India" : params.region === "UAE" ? "United Arab Emirates" : params.region === "USA" ? "United States" : "Global"),
    category: params.category || "AGENCY_DIRECTORY",
    free_status: "FREE",
    free_tier_details: params.freeDetails || "Free basic listing with website URL and company profile",
    requires_account: params.requiresAccount ?? true,
    requires_editorial_review: params.editorialReview ?? true,
    submission_type: params.subType || "FORM",
    recommended_dgs_target_page: params.targetPage || "https://www.dgeniussolutions.com/",
    recommended_service: params.service || "Digital Marketing & AI",
    recommended_content: params.content || "Company profile featuring DGS agency services and Khar West headquarters",
    recommended_anchor_strategy: params.anchor || "BRANDED",
    link_type: params.linkType || "DIRECTORY",
    dofollow_status: params.dofollow || "DOFOLLOW",
    estimated_quality: params.quality || "HIGH",
    topical_relevance: params.topical || 85,
    geo_relevance: params.geo || 90,
    traffic_potential: params.traffic || 80,
    editorial_quality: params.editorial || 85,
    spam_risk: params.spam || 0,
    acceptance_probability: params.acceptance || 85,
    value_score: params.value || 88,
    difficulty_score: params.diff || 25,
    priority_score: params.priority || 88,
    priority_tier: params.tier || "P0",
    authority_score: params.auth || 88,
    spam_status: "SAFE",
    verification_date: "2026-10-04",
    last_verified: "2026-10-04T00:00:00.000Z",
    source: "CURATED_SEED",
    status: params.status || "QUALIFIED",
    assigned_to: params.assigned || null,
    notes: params.notes || "Verified legitimate free tier directory.",
    evidence: params.evidence || "Direct action URL verified active.",
  };
}

